update pages set contenu = '{"sections":[]}'::jsonb where path = '/expertises/robotique/fanuc/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Fanuc robotique","mecanisme":"Un technicien qui lit les alarmes du contrôleur, teste axe par axe et reprend le programme lui-même. Robots Fanuc et machines Robodrill, Roboshot, Robocut traités par les mêmes équipes, avec vos sauvegardes datées avant de quitter le site.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"+ 80","libelle":"clients réguliers, beaucoup arrivés par une panne"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"Le robot jaune est à l''arrêt, un code défaut clignote sur le pupitre, et personne sur le site ne sait le lire.","puces":[{"accroche":"Le roboticien Fanuc est introuvable.","texte":"Vos offres restent ouvertes des mois. Pendant ce temps, la cellule tourne sans personne pour la tenir."},{"accroche":"La batterie d''encodeur meurt en silence.","texte":"Le jour de la coupure, les positions et le programme partent avec elle. La remise en service devient une reconstruction."},{"accroche":"Le robot dérive avant de lâcher.","texte":"Le mastering se décale, la pièce n''est plus prise au bon endroit, la qualité décroche bien avant l''immobilisation."},{"accroche":"Le plus souvent, le bras n''est que le messager.","texte":"Convoyeur, préhenseur, vision, automate de ligne : la cause est hors de la baie, et on démonte le robot pour rien."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"La recherche de cause racine, pas l''échange de pièce","texte":"lecture des alarmes du contrôleur R-30iB et des générations voisines, contrôle des servomoteurs, essais en charge."},"benefice":"Vous arrêtez de remplacer des organes sains pendant que la ligne attend."},{"prestation":{"accroche":"Le remastering et la reprise de points","texte":"après une perte des références."},"benefice":"Le robot retrouve sa trajectoire avec méthode, contrôle de répétabilité à l''appui, pas par essais successifs."},{"prestation":{"accroche":"Vos programmes sauvegardés et datés","texte":"programmes, paramètres et positions de chaque contrôleur, archivés à chaque évolution."},"benefice":"Le jour où une carte lâche, on recharge au lieu de tout réécrire."},{"prestation":{"accroche":"Les organes d''usure suivis dans l''ordre","texte":"freins, réducteurs, batteries d''encodeurs, faisceaux de bras, connectique de l''axe 6."},"benefice":"Le défaut fantôme du faisceau se teste en mouvement, donc il se trouve."},{"prestation":{"accroche":"Toute la gamme, pas seulement le bras","texte":"LR Mate, M-10, M-20, R-2000, M-710, ARC Mate, cobots CRX, delta et SCARA."},"benefice":"Un seul interlocuteur pour un parc mixte, même quand les séries n''ont rien à voir entre elles."},{"prestation":{"accroche":"Les machines à commande numérique Fanuc","texte":"Robodrill (broche, avances, changeur d''outil), Roboshot en injection, Robocut en électroérosion."},"benefice":"Vos centres d''usinage et vos presses ne partent plus chez un second prestataire."},{"prestation":{"accroche":"Le rétrofit chiffré face au remplacement","texte":"contrôleur obsolète, pièce plus fabriquée, application à faire évoluer."},"benefice":"La décision se prend sur deux chiffres, pas sur le catalogue du constructeur."}],"prose":[{"texte":"Le bras n''est jamais seul : l''armoire, l''automate et les sécurités relèvent de nos équipes [automatisme](/expertises/automatisme/), et la cellule complète de notre [maintenance robotique](/expertises/robotique/). Un parc entier à remettre sous suivi passe par le [contrat Zéro arrêt](/offres/zero-arret/) ; un robot immobilisé maintenant, par le [dépannage industriel](/offres/depannage-industriel/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la panne","texte":"modèle Fanuc, contrôleur, code alarme, moment du cycle. Quelques minutes au téléphone évitent un déplacement pour rien."},{"titre":"Un technicien vous rappelle dans l''heure.","texte":"Vous savez rapidement si nous avons le roboticien, et lequel."},{"titre":"Nous cherchons la cause avant de démonter","texte":"alarmes du contrôleur, essais axe après axe, contrôle des périphériques et des sécurités de cellule."},{"titre":"Nous réparons et remettons en service","texte":"pièce changée, points repris, essais avec vos opérateurs sur le cycle complet jusqu''au retour de la cadence."},{"titre":"Les sauvegardes sont reprises et datées","texte":"avant de quitter le site, positions et paramètres compris."},{"titre":"Vous recevez le rapport écrit","texte":"cause racine, travaux réalisés, pièces à mettre en stock, points à surveiller au prochain passage."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Vos programmes, vos recettes et vos données de production restent chez vous.","texte":"Condition non négociable, quelle que soit la durée de la mission."},{"accroche":"Aucune vente de robot, aucune licence, aucun carnet de commandes constructeur à remplir.","texte":"Migen n''est ni revendeur ni intégrateur agréé : nous gardons la liberté sur le choix des pièces de rechange."}]},{"type":"cta","question":"Besoin d''un technicien capable de lire le code défaut de votre robot Fanuc aujourd''hui ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/expertises/robotique/fanuc/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Maintenance des équipements critiques d''un équipementier automobile","texte":"techniciens intégrés au quotidien sur systèmes automatisés, lignes et convoyeurs, avec des roboticiens ABB et Fanuc parmi les spécialités mobilisables, depuis 2025","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"Maintenance d''un parc d''usinage de précision, un technicien à temps plein","texte":"centres d''usinage à grande vitesse, presses et diagnostic sur commandes numériques, sur un parc multimarques, 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Contrôle de chantier sur des projets d''automatisation logistique","texte":"plusieurs intervenants intégrés aux équipes, roboticiens ABB et Fanuc parmi les spécialités engagées, 2025 à 2026","lienLibelle":"Étude de cas ALSTEF Group : collaboration","lienHref":"/preuves/alstef-group/"},{"titre":"18 à 25 techniciens sur plusieurs sites automobiles en transition vers l''électrique","texte":"préventif et curatif portés par le même dispositif sur des parcs machines qui changent pendant qu''ils produisent, depuis juin 2023","lienLibelle":"Étude de cas STELLANTIS : sites du Grand Est","lienHref":"/preuves/stellantis-grand-est/"},{"titre":"Montée en cadence accompagnée dans plusieurs usines françaises","texte":"trois à cinq techniciens sur lignes de production, ateliers de fabrication et préventif, depuis septembre 2024","lienLibelle":"Étude de cas VALEO : plusieurs usines","lienHref":"/preuves/valeo-usines/"}]},{"type":"objections","questions":[{"question":"Êtes-vous partenaire officiel Fanuc ?","reponse":"Non, et nous le disons clairement. Migen n''est ni revendeur ni intégrateur agréé : nous sommes une entreprise de maintenance industrielle indépendante. Nous entretenons le matériel déjà installé chez vous. Cette indépendance a une conséquence directe : nous n''avons aucun catalogue à écouler, et chaque prestation est chiffrée sur devis, sans surprise à la facture."},{"question":"Intervenez-vous aussi sur Robodrill, Roboshot et Robocut ?","reponse":"Oui. Ces trois gammes relèvent de la machine-outil à commande numérique, pas du bras robotisé : usinage CNC pour Robodrill, moulage par injection pour Roboshot, électroérosion à fil pour Robocut. Nos mécaniciens et nos électrotechniciens y interviennent au même titre que sur un robot, avec le même rapport écrit en sortie. C''est utile quand votre atelier mélange les deux mondes."},{"question":"Mon contrôleur est ancien : faut-il le remplacer ?","reponse":"Pas forcément. Tant que les pièces de rechange existent et que le fonctionnement reste sain, la maintenance reste plus rentable que le rétrofit. Nous chiffrons les deux options en parallèle, avec les coûts en face, pour que la décision vous appartienne. Le jour où les pièces deviennent introuvables, vous aurez déjà le chiffre sous les yeux."},{"question":"Pouvez-vous reprendre un programme écrit par un autre prestataire ?","reponse":"Oui, c''est le cas le plus fréquent. Nous auditons l''existant, nous l''enregistrons, nous le documentons, puis nous le modifions proprement. Roboguide permet de valider une trajectoire hors ligne avant de la charger, sans immobiliser la production. Vous récupérez la main sur votre installation, avec une sauvegarde datée à chaque évolution."},{"question":"Qui répond de la sécurité dans la cellule ?","reponse":"Nos techniciens, dans votre cadre. Habilitations électriques vérifiées avant la mission, consignation, travaux en armoire, plan de prévention signé, contrôle des sécurités de cellule avant la remise en production. Notre démarche MASE et notre évaluation EcoVadis sont transmises avec chaque plan de prévention. Les titres sont contrôlés avant l''intervention, pas après."},{"question":"Couvrez-vous notre région, et un parc d''un seul robot ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et 10 hubs de techniciens à Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon et Nantes. Nos techniciens sont mobiles et interviennent au-delà de ces villes. Une visite préventive annuelle et une priorité en cas de panne n''exigent pas un dispositif plus lourd que nécessaire."}]},{"type":"ctaFinal","question":"Besoin que votre parc Fanuc tienne sa cadence toute l''année au lieu de décrocher par paliers ?","bouton":"Demander une intervention"}]'::jsonb) where path = '/expertises/robotique/fanuc/';
